# json2video_render.py
import requests
import time
import json
import os

# --- Configuration ---
JSON2VIDEO_API_KEY = os.environ.get("JSON2VIDEO_API_KEY", "YOUR_JSON2VIDEO_API_KEY")
BASE_URL = "https://api.json2video.com/v2"

# Load the script generated by Gemini (or your source)
with open("script.json", "r", encoding="utf-8") as f:
    story = json.load(f)

# --- Step 1: Build the Movie JSON ---
# This creates 6 scenes, each 10 seconds long, for a total of 60 seconds.
scenes = []
for i, scene_data in enumerate(story["scenes"], start=1):
    # NOTE: You must provide publicly accessible image URLs.
    # JSON2Video cannot pull from local files or private storage.
    # Replace the placeholder with your actual image hosting logic.
    image_url = f"https://your-cdn.com/placeholder_scene_{i}.jpg"

    scene = {
        "duration": 10,  # Each scene lasts 10 seconds
        "elements": [
            {
                "type": "image",
                "src": image_url,
                "duration": 10
            },
            {
                "type": "text",
                "text": scene_data["on_screen_text"],
                "duration": 10,
                "style": "001"  # Or your preferred text style
            }
        ]
    }
    scenes.append(scene)

movie_payload = {
    "resolution": "full-hd",  # 1920x1080
    "scenes": scenes
}

# --- Step 2: Submit the Render Job ---
print("🚀 Submitting render job to JSON2Video...")
response = requests.post(
    f"{BASE_URL}/movies",
    headers={
        "x-api-key": JSON2VIDEO_API_KEY,
        "Content-Type": "application/json"
    },
    json=movie_payload,
    timeout=30
)
response.raise_for_status()
project_data = response.json()

if not project_data.get("success"):
    raise RuntimeError(f"Failed to create project: {project_data}")

project_id = project_data["project"]
print(f"✅ Project created. ID: {project_id}")

# --- Step 3: Poll for Completion ---
print("⏳ Rendering in progress...")
max_wait_seconds = 600  # 10 minutes timeout
poll_interval = 10      # Check every 10 seconds
start_time = time.time()

video_url = None

while time.time() - start_time < max_wait_seconds:
    status_response = requests.get(
        f"{BASE_URL}/movies",
        headers={"x-api-key": JSON2VIDEO_API_KEY},
        params={"project": project_id},
        timeout=15
    )
    status_response.raise_for_status()
    movie_info = status_response.json().get("movie", {})
    status = movie_info.get("status")

    if status == "done":
        video_url = movie_info.get("url")
        print(f"🎉 Render complete! Video URL: {video_url}")
        break
    elif status in ["error", "timeout"]:
        raise RuntimeError(f"Render failed. Status: {status}. Details: {movie_info}")
    else:
        print(f"   ... status is '{status}', checking again in {poll_interval}s")
        time.sleep(poll_interval)

if not video_url:
    raise TimeoutError("Render did not complete within the maximum wait time.")

# --- Step 4: (Optional) Download the Video ---
# You can download the video to your runner for the YouTube upload step.
output_path = "output/short_final.mp4"
os.makedirs("output", exist_ok=True)
print(f"⬇️ Downloading video to {output_path}...")

with requests.get(video_url, stream=True, timeout=60) as r:
    r.raise_for_status()
    with open(output_path, "wb") as f:
        for chunk in r.iter_content(chunk_size=8192):
            f.write(chunk)

print(f"✅ Video saved to {output_path}")
